package com.autocare.service;
import com.autocare.dto.request.*; import com.autocare.dto.response.*; import com.autocare.entity.*; import com.autocare.enums.*; import com.autocare.exception.*; import com.autocare.repository.*; import com.autocare.security.*; import jakarta.persistence.EntityManager; import jakarta.transaction.Transactional; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service @Transactional public class AppointmentService {
 private final AppointmentRepository appointments; private final ServiceCaseRepository cases; private final ServiceIssueRepository issues; private final CustomerRepository customers; private final VehicleRepository vehicles; private final CurrentUserService current; private final EntityManager em;
 public AppointmentService(AppointmentRepository a,ServiceCaseRepository c,ServiceIssueRepository i,CustomerRepository cu,VehicleRepository v,CurrentUserService x,EntityManager e){appointments=a;cases=c;issues=i;customers=cu;vehicles=v;current=x;em=e;}
 public AppointmentResponse create(AppointmentRequest r){ Customer customer=current.requireCurrentCustomer(); Vehicle vehicle=vehicle(r.vehicleId()); if(!vehicle.getCustomer().getId().equals(customer.getId()))throw new AccessDeniedException("You cannot book another customer's vehicle"); validate(r.requestedDate(),r.requestedTime(),r.serviceType(),r.issueDescription()); return appointment(appointments.save(new Appointment(next("appointment_business_id_seq","APT"),customer,vehicle,r.requestedDate(),r.requestedTime(),r.serviceType(),blank(r.issueDescription()),Priority.NORMAL))); }
 public List<AppointmentResponse> list(String status){CurrentUser actor=current.requireCurrentUser(); List<Appointment> data=workshop(actor)?(status==null?appointments.findAll():appointments.findByStatus(AppointmentStatus.valueOf(status))):appointments.findByCustomer_CustomerId(current.requireCurrentCustomer().getCustomerId()); return data.stream().map(this::appointment).toList();}
 public AppointmentResponse get(String id){Appointment a=find(id); access(a);return appointment(a);} public AppointmentResponse confirm(String id){return transition(id,AppointmentStatus.REQUESTED,AppointmentStatus.CONFIRMED);} public AppointmentResponse cancel(String id){Appointment a=find(id);CurrentUser actor=current.requireCurrentUser();if(!workshop(actor))access(a);if(a.getStatus()!=AppointmentStatus.REQUESTED&&a.getStatus()!=AppointmentStatus.CONFIRMED)throw new IllegalStateException("Appointment cannot be cancelled");a.status(AppointmentStatus.CANCELLED);return appointment(a);} public AppointmentResponse noShow(String id){return transition(id,AppointmentStatus.CONFIRMED,AppointmentStatus.NO_SHOW);}
 public ServiceCaseResponse checkIn(String id){CurrentUser actor=current.requireCurrentUser();requireWorkshop(actor);Appointment a=find(id);if(a.getStatus()!=AppointmentStatus.CONFIRMED)throw new IllegalStateException("Only confirmed appointments can be checked in");if(cases.findByAppointment_AppointmentId(id).isPresent())throw new DuplicateResourceException("Appointment has already been checked in"); ServiceCase sc=cases.save(new ServiceCase(next("service_case_business_id_seq","SRV"),a.getCustomer(),a.getVehicle(),a,VisitType.APPOINTMENT,a.getServiceType(),a.getPriority(),null)); if(a.getIssueDescription()!=null)issues.save(new ServiceIssue(sc,a.getIssueDescription(),null,actor.username()));a.status(AppointmentStatus.CHECKED_IN);return response(sc);}
 public ServiceCaseResponse walkIn(WalkInRequest r){CurrentUser actor=current.requireCurrentUser();requireWorkshop(actor);Customer c=customers.findByCustomerId(r.customerId()).orElseThrow(()->new ResourceNotFoundException("Customer not found"));Vehicle v=vehicle(r.vehicleId());if(!v.getCustomer().getId().equals(c.getId()))throw new IllegalStateException("Vehicle does not belong to customer");validate(null,null,r.serviceType(),r.issueDescription());ServiceCase sc=cases.save(new ServiceCase(next("service_case_business_id_seq","SRV"),c,v,null,VisitType.WALK_IN,r.serviceType(),r.priority(),null));if(blank(r.issueDescription())!=null)issues.save(new ServiceIssue(sc,blank(r.issueDescription()),blank(r.additionalNotes()),actor.username()));return response(sc);}
 private AppointmentResponse transition(String id,AppointmentStatus from,AppointmentStatus to){CurrentUser actor=current.requireCurrentUser();requireWorkshop(actor);Appointment a=find(id);if(a.getStatus()!=from)throw new IllegalStateException("Invalid appointment status transition");a.status(to);return appointment(a);} private void validate(LocalDate d,LocalTime t,ServiceType type,String issue){if(type==ServiceType.SPECIFIC_ISSUE||type==ServiceType.BOTH)if(blank(issue)==null)throw new IllegalStateException("Issue description is required for this service type");if(d!=null&&LocalDateTime.of(d,t).isBefore(LocalDateTime.now()))throw new IllegalStateException("Appointment date and time must be in the future");} private Appointment find(String id){return appointments.findByAppointmentId(id).orElseThrow(()->new ResourceNotFoundException("Appointment not found"));} private Vehicle vehicle(String id){return vehicles.findByVehicleId(id).orElseThrow(()->new ResourceNotFoundException("Vehicle not found"));} private void access(Appointment a){CurrentUser x=current.requireCurrentUser();if(workshop(x))return;if(!a.getCustomer().getUser().getId().equals(x.id()))throw new AccessDeniedException("You cannot access this appointment");} private boolean workshop(CurrentUser x){return Set.of("EMPLOYEE","MANAGER","OWNER").contains(x.role());} private void requireWorkshop(CurrentUser x){if(!workshop(x))throw new AccessDeniedException("Workshop access is required");} private String next(String seq,String prefix){Number n=(Number)em.createNativeQuery("select nextval('"+seq+"')").getSingleResult();return prefix+"-%06d".formatted(n.longValue());} private String blank(String v){return v==null||v.isBlank()?null:v.trim();} private AppointmentResponse appointment(Appointment a){Vehicle v=a.getVehicle();Customer c=a.getCustomer();return new AppointmentResponse(a.getAppointmentId(),c.getCustomerId(),c.getName(),c.getPhone(),v.getVehicleId(),v.getMake()+" "+v.getModel(),v.getLicensePlate(),a.getRequestedDate(),a.getRequestedTime(),a.getServiceType(),a.getIssueDescription(),a.getPriority(),a.getStatus());} private ServiceCaseResponse response(ServiceCase c){return new ServiceCaseResponse(c.getServiceCaseId(),c.getCustomer().getCustomerId(),c.getVehicle().getVehicleId(),c.getAppointment()==null?null:c.getAppointment().getAppointmentId(),c.getVisitType(),c.getServiceType(),c.getPriority(),c.getStatus(),c.getCheckInTime());}
}
